import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { useSettings } from '@/state/settings';

/** Generated by scripts/render-sounds.mjs. */
const SOURCES = {
  tap: require('../../assets/sounds/tap.wav'),
  correct: require('../../assets/sounds/correct.wav'),
  wrong: require('../../assets/sounds/wrong.wav'),
  tick: require('../../assets/sounds/tick.wav'),
  rankup: require('../../assets/sounds/rankup.wav'),
} as const;

export type SoundName = keyof typeof SOURCES;

const VOLUME: Record<SoundName, number> = { tap: 0.35, correct: 0.55, wrong: 0.5, tick: 0.45, rankup: 0.7 };

let players: Partial<Record<SoundName, AudioPlayer>> = {};
let ready = false;

/** Preload players once. Sound respects the phone's silent switch and mixes with the user's music. */
export async function initSounds(): Promise<void> {
  if (ready) return;
  ready = true;
  try {
    await setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' });
    players = Object.fromEntries(
      (Object.keys(SOURCES) as SoundName[]).map((name) => {
        const p = createAudioPlayer(SOURCES[name], { keepAudioSessionActive: true });
        p.volume = VOLUME[name];
        return [name, p];
      }),
    );
  } catch (e) {
    if (__DEV__) console.warn('sounds unavailable', e);
  }
}

export function play(name: SoundName): void {
  if (!useSettings.getState().sound) return;
  const p = players[name];
  if (!p) return;
  try {
    void p.seekTo(0);
    p.play();
  } catch {
    // Never let a sound effect break gameplay.
  }
}
